def solve():
    max_n = 0
    for a in range(9):
        for b in range(9):
            for i in range(min(a, b) + 1):
                if a + b - i > 8:
                    continue

                s1_max = 2**i
                s2_max = 2**a - 2**i
                s3_max = 2**b - 2**i
                s4_max = 2**8 - 2**a - 2**b + 2**i

                # s3 + s4 <= 7 - a
                # s2 + s4 <= 7 - b

                limit_s4 = min(s4_max, 7-a, 7-b)
                if limit_s4 < 0:
                    continue

                for s4 in range(limit_s4 + 1):
                    s2 = min(s2_max, 7 - b - s4)
                    s3 = min(s3_max, 7 - a - s4)
                    if s2 < 0: s2 = 0
                    if s3 < 0: s3 = 0

                    n = s1_max + s2 + s3 + s4
                    if n > max_n:
                        max_n = n

    return max_n

print(solve())
